/// The spacing of doubles at `x > 0`.
fn ulp(x: f64) -> f64 {
    f64::from_bits(x.to_bits() + 1) - x
}

/// `c₂ = 1`: rounding `r_E + r_S` before `d` is taken from it moves the external gap by up to half an
/// ulp of the sum, a relative error in `d` of at most `u·s/d ≈ u`, which is worth `κ` ulp of `A`.
/// `c₁ = 4` is what is left: `x − sin x` within 2 ulp (`shadow.rs`), then two products and the sum.
/// Measured: 1.85 ulp where `κ < 1`, and with `c₁ = 2` every row fits under `c₂ = 0.71`.
const C1: f64 = 4.0;
const C2: f64 = 1.0;

/// `A` on every row within `c₁ + c₂κ` ulp of the reference, and exactly 0 where the discs are apart.
#[test]
fn the_lens_area_is_within_its_condition_bound_of_the_reference() {
    let (mut flat, mut fit, mut worst) = (0.0_f64, 0.0_f64, 0.0_f64);
    for &(re, rs, d, a_hi, a_lo, _, _, kappa) in &REFERENCE {
        let a = lens_area(d, re, rs);
        if a_hi == 0.0 {
            assert_eq!(
                a, 0.0,
                "r_E {re:e}, r_S {rs:e}, d {d:e}: the discs are apart"
            );
            continue;
        }
        let err = ((a - a_hi) - a_lo).abs() / ulp(a_hi);
        assert!(
            err <= C1 + C2 * kappa,
            "r_E {re:e}, r_S {rs:e}, d {d:e}: {err:.2} ulp against a bound of {:.2} (κ {kappa:.2e})",
            C1 + C2 * kappa
        );
        worst = worst.max(err / (C1 + C2 * kappa));
        if kappa < 1.0 {
            flat = flat.max(err);
        }
        if kappa > 0.0 {
            fit = fit.max((err - 2.0) / kappa);
        }
    }
    println!(
        "lens area: worst {worst:.3} of the bound; {flat:.2} ulp where κ < 1; c₂ {fit:.3} with c₁ = 2"
    );
}

/// `ν` on every row within the bound `A`'s carries through `1 − A/(π r_S²)`: `(1 − ν)` times `A`'s
/// relative error plus that of `π r_S²` and the division, `3.4u`, then half an ulp of 1 for the
/// subtraction. In units of `u = 2⁻⁵³`, since near the umbra `ν` is an absolute quantity: the bound
/// does not promise its relative accuracy where `ν → 0`, and nothing that uses it needs that.
#[test]
fn the_visible_fraction_is_within_the_bound_the_area_carries() {
    let u = f64::EPSILON / 2.0;
    let mut worst = 0.0_f64;
    for &(re, rs, d, _, _, nu_hi, nu_lo, kappa) in &REFERENCE {
        let nu = masking_ratio(d, re, rs);
        let err = ((nu - nu_hi) - nu_lo).abs() / u;
        let bound = (1.0 - nu_hi) * (2.0 * (C1 + C2 * kappa) + 3.4) + 0.5;
        assert!(
            err <= bound,
            "r_E {re:e}, r_S {rs:e}, d {d:e}: |Δν| {err:.2}u against {bound:.2}u"
        );
        worst = worst.max(err / bound);
    }
    println!("visible fraction: worst {worst:.3} of its bound");
}

/// Orekit's `SolarRadiationPressure.maskingRatio`: the same lens as two `acos` segments on the
/// chord, each less its triangle, with `ANGULAR_MARGIN = 1e-10` on both plateaus and the `acos`
/// arguments clamped inside `±nextDown(1)`. The arrangement `lens_area` replaced.
#[expect(
    clippy::similar_names,
    reason = "Orekit's names, to read against its source"
)]
fn orekit_masking_ratio(separation: f64, alpha_central: f64, alpha_sun: f64) -> f64 {
    use std::f64::consts::PI;
    const ANGULAR_MARGIN: f64 = 1.0e-10;
    if separation - alpha_central + alpha_sun <= ANGULAR_MARGIN {
        0.0
    } else if separation - alpha_central - alpha_sun < -ANGULAR_MARGIN {
        let s_ea2 = separation * separation;
        let oo2s_ea = 1.0 / (2.0 * separation);
        let a_s2 = alpha_sun * alpha_sun;
        let a_e2 = alpha_central * alpha_central;
        let a_e2m_a_s2 = a_e2 - a_s2;
        let alpha1 = (s_ea2 - a_e2m_a_s2) * oo2s_ea;
        let alpha2 = (s_ea2 + a_e2m_a_s2) * oo2s_ea;
        let almost1 = f64::from_bits(0x3FEF_FFFF_FFFF_FFFF);
        let a1o_a_s = (alpha1 / alpha_sun).clamp(-almost1, almost1);
        let a_s2m_a12 = (a_s2 - alpha1 * alpha1).max(f64::MIN_POSITIVE);
        let a2o_a_e = (alpha2 / alpha_central).clamp(-almost1, almost1);
        let a_e2m_a22 = (a_e2 - alpha2 * alpha2).max(f64::MIN_POSITIVE);
        let p1 = a_s2 * a1o_a_s.acos() - alpha1 * a_s2m_a12.sqrt();
        let p2 = a_e2 * a2o_a_e.acos() - alpha2 * a_e2m_a22.sqrt();
        1.0 - (p1 + p2) / (PI * a_s2)
    } else {
        1.0
    }
}

/// The distance of Orekit's arrangement to the reference on the same grid: 6.5e-7 in `ν` 1.1e-9 rad
/// inside either tangency of the 400 km pair, where it returns `ν = −6.5e-7`, and 1e-10 to 9e-10
/// across that penumbra. A comparison, kept to reproduce the figure `shadow.rs` quotes.
#[test]
#[ignore = "comparator: the distance of Orekit's arrangement, not a verdict"]
fn orekit_masking_ratio_distance_to_the_reference() {
    let mut worst = (0.0_f64, 0_usize);
    for (i, &(re, rs, d, _, _, nu_hi, nu_lo, _)) in REFERENCE.iter().enumerate() {
        let err = ((orekit_masking_ratio(d, re, rs) - nu_hi) - nu_lo).abs();
        if err > worst.0 {
            worst = (err, i);
        }
    }
    let (re, rs, d, _, _, nu_hi, _, _) = REFERENCE[worst.1];
    println!(
        "Orekit's masking ratio: worst |Δν| {:.2e} at r_E {re:e}, r_S {rs:e}, d {d:e} (ν {nu_hi:.3e}), shipped {:.2e}",
        worst.0,
        ((masking_ratio(d, re, rs) - nu_hi) - REFERENCE[worst.1].6).abs()
    );
}
